def qsort(a):
    if len(a) <= 1:
        return a
    pivot, rest = a[0], a[1:]
    left = [v for v in rest if v < pivot]
    right = [v for v in rest if v >= pivot]
    return qsort(left) + [pivot] + qsort(right)

